"""Generates "FM27 Skin Editor.app": a macOS application bundle whose executable is a shell script with the
project, workspace and venv paths baked in. Regenerate to update the paths."""
import os
import plistlib
import shlex
import shutil
import sys
from pathlib import Path

from . import config

APP_NAME = "FM27 Skin Editor.app"
BUNDLE_ID = "com.fm27skineditor.launcher"
APP_ID = "fm27-skin-editor"

SCRIPT = r'''#!/bin/bash
# Target shell: macOS /bin/bash 3.2. No bash 4 constructs (checked by the test suite).
# Generated by FM27 Skin Editor (Setup > Create launcher, or: python -m skin_editor launcher).
# Paths are baked in. Regenerate after moving the project folder or the workspace.
PROJECT=@PROJECT@
WS=@WS@
CFGROOT=@CFGROOT@
VENV=@VENV@
APP_ID=@APP_ID@

LOG="$WS/logs/launcher.log"
[ -d "$WS/logs" ] || LOG="$HOME/Library/Logs/FM27SkinEditor-launcher.log"
mkdir -p "$(dirname "$LOG")"
exec >>"$LOG" 2>&1
echo "---- $(date '+%Y-%m-%d %H:%M:%S') launch"

LOCK=""
fail() {
  echo "FAIL: $1"
  [ -n "$LOCK" ] && rmdir "$LOCK" 2>/dev/null
  osascript -e 'on run argv' \
    -e 'display dialog (item 1 of argv) buttons {"OK"} default button 1 with icon stop with title "FM27 Skin Editor"' \
    -e 'end run' -- "$1

Log: $LOG" >/dev/null 2>&1
  exit 1
}
note() {
  osascript -e 'on run argv' -e 'display notification (item 1 of argv) with title "FM27 Skin Editor"' \
    -e 'end run' -- "$1" >/dev/null 2>&1
}

[ -f "$PROJECT/skin_editor/__main__.py" ] || fail "The app folder was moved or deleted:
$PROJECT

Move it back, or create the launcher again. Open Terminal and run this, with NEW_FOLDER replaced by the folder that now contains skin_editor:

cd \"NEW_FOLDER\" && python3.12 -m skin_editor launcher --yes

If python3.12 is not installed, use the first one you have of python3.13, python3.11, python3.14 or python3.10 (the order the launcher uses). Never a bare python3: the newest version may have no prebuilt packages."
[ -d "$WS" ] || fail "The workspace folder was moved or deleted:
$WS
Move it back, or create the launcher again."

# ---- Python environment (first run: create the venv and install requirements)
PY="$VENV/bin/python"
if ! [ -x "$PY" ] || ! "$PY" -c 'import UnityPy' 2>/dev/null; then
  if ! [ -x "$PY" ]; then
    BASE=""
    for v in 3.12 3.13 3.11 3.14 3.10; do
      for c in /opt/homebrew/bin/python$v /usr/local/bin/python$v \
               /Library/Frameworks/Python.framework/Versions/$v/bin/python$v "$(command -v python$v 2>/dev/null)"; do
        if [ -n "$c" ] && [ -x "$c" ]; then BASE="$c"; break 2; fi
      done
    done
    [ -n "$BASE" ] || fail "No suitable Python was found (3.12 preferred; 3.10 to 3.14 work). Install Python 3.12 (python.org installer or Homebrew python@3.12) and click again. A bare python3 is never used: the newest version may have no prebuilt packages."
    echo "creating venv with $BASE"
    "$BASE" -m venv "$VENV" || fail "Creating the Python environment failed."
  fi
  note "First run: installing components. This can take a few minutes."
  "$PY" -m pip install --upgrade pip
  "$PY" -m pip install -r "$PROJECT/requirements.txt" || fail "Installing the Python packages failed."
fi

export FM27SE_WORKSPACE="$CFGROOT"
cd "$PROJECT" || fail "Cannot open the app folder: $PROJECT"
INFO="$("$PY" -m skin_editor paths)" || fail "The app could not read its configuration."
PORT="$(echo "$INFO" | sed -n 1p)"
STATE="$(echo "$INFO" | sed -n 2p)"
[ "$STATE" = "$WS/state" ] || fail "The workspace has moved since this launcher was created.
Launcher: $WS
Now: $(dirname "$STATE")
Create the launcher again from the Setup tab."
mkdir -p "$STATE"

# WHO: none (port free) | ours (this workspace's current server) | stale (this app, another session) | foreign
probe() {
  R="$(curl -s -m 2 "http://127.0.0.1:$PORT/ping")"
  RC=$?
  if [ $RC -eq 7 ]; then WHO=none; return; fi
  ID="$(cat "$STATE/instance-id" 2>/dev/null)"
  if [ $RC -eq 0 ] && [ -n "$ID" ] && [ "$R" = "$APP_ID $ID" ]; then WHO=ours; return; fi
  case "$R" in
    "$APP_ID "*) WHO=stale ;;
    *) WHO=foreign ;;
  esac
}
wait_ours() {
  i=0
  while [ $i -lt "$1" ]; do
    probe
    [ "$WHO" = ours ] && return 0
    sleep 0.5
    i=$((i+1))
  done
  return 1
}

# ---- one launcher at a time; a second click waits for the first and then opens the same session
LOCK="$STATE/launcher.lock"
[ -d "$LOCK" ] && [ -n "$(find "$LOCK" -maxdepth 0 -mmin +15 2>/dev/null)" ] && rmdir "$LOCK" 2>/dev/null
if ! mkdir "$LOCK" 2>/dev/null; then
  echo "another launch is in progress; waiting for it"
  LOCK=""
  wait_ours 120 || fail "Another launch is still in progress and the server did not answer."
else
  probe
  echo "port $PORT: $WHO"
  case "$WHO" in
    foreign) fail "Port $PORT is used by another program. Change server.port in
$CFGROOT/config.json
or quit that program, then click again." ;;
    stale) fail "An FM27 Skin Editor server from another session is running on port $PORT and this launcher has no address for it. Quit it with the Quit server button in its browser tab (or log out), then click again." ;;
    none)
      rm -f "$STATE/last-url" "$STATE/instance-id"
      echo "starting server"
      nohup "$PY" -m skin_editor serve --no-browser >>"$WS/logs/server.log" 2>&1 &
      wait_ours 60 || fail "The server did not start. See $WS/logs/server.log" ;;
  esac
  rmdir "$LOCK" 2>/dev/null
  LOCK=""
fi

URL="$(cat "$STATE/last-url" 2>/dev/null)"
[ -n "$URL" ] || fail "The server is running but did not record its address."
echo "opening browser"
open "$URL" || fail "Could not open the browser."
exit 0
'''


def candidates():
    """Target folders in order of preference: /Applications when writable, else next to the project folder."""
    out = []
    apps = Path("/Applications")
    if apps.is_dir() and os.access(apps, os.W_OK):
        out.append(apps)
    out.append(config.resource_root().parent)
    return out


def plan(cfg):
    ws = config.workspace(cfg)
    venv = Path(sys.prefix) if sys.prefix != sys.base_prefix else config.resource_root() / ".venv"
    dirs = candidates()
    return {"target_dir": str(dirs[0]), "choices": [str(d) for d in dirs], "app": str(dirs[0] / APP_NAME),
            "exists": (dirs[0] / APP_NAME).exists(), "project": str(config.resource_root()),
            "workspace": str(ws.root), "venv": str(venv), "macos": sys.platform == "darwin"}


def script_text(project, workspace, cfgroot, venv):
    s = SCRIPT
    for key, val in (("PROJECT", project), ("WS", workspace), ("CFGROOT", cfgroot), ("VENV", venv), ("APP_ID", APP_ID)):
        s = s.replace("@%s@" % key, shlex.quote(str(val)))
    return s


def generate(cfg, target_dir, project=None, venv=None):
    """Write <target_dir>/FM27 Skin Editor.app. Replaces an earlier launcher; refuses to touch any other app."""
    ws = config.workspace(cfg)
    p = plan(cfg)
    app = Path(target_dir).expanduser() / APP_NAME
    if app.exists():
        try:
            with open(app / "Contents" / "Info.plist", "rb") as f:
                ours = plistlib.load(f).get("CFBundleIdentifier") == BUNDLE_ID
        except Exception:
            ours = False
        if not ours:
            raise RuntimeError("%s exists and was not created by this app; remove it yourself first" % app)
        shutil.rmtree(app)
    macos = app / "Contents" / "MacOS"
    macos.mkdir(parents=True)
    (app / "Contents" / "Resources").mkdir()
    with open(app / "Contents" / "Info.plist", "wb") as f:
        plistlib.dump({"CFBundleName": "FM27 Skin Editor", "CFBundleDisplayName": "FM27 Skin Editor",
                       "CFBundleIdentifier": BUNDLE_ID, "CFBundleExecutable": "launcher", "CFBundlePackageType": "APPL",
                       "CFBundleVersion": "1", "CFBundleShortVersionString": "1.0", "CFBundleInfoDictionaryVersion": "6.0",
                       "LSMinimumSystemVersion": "11.0", "NSHighResolutionCapable": True}, f)
    exe = macos / "launcher"
    exe.write_text(script_text(project or p["project"], ws.root, config.default_workspace(), venv or p["venv"]),
                   encoding="utf-8", newline="\n")                   # a shell script keeps LF on every OS (a CRLF script does not parse under bash)
    exe.chmod(0o755)
    return {"app": str(app), "project": str(project or p["project"]), "workspace": str(ws.root),
            "venv": str(venv or p["venv"]), "log": str(ws.logs / "launcher.log")}
